private List<DesktopWindowInfo> ApplyRegexFilters(List<DesktopWindowInfo> windows, MaaInterface.MaaResourceControllerWin32 win32)
{
    // Both discovery and the selected-window validity check use this overload.
    // Multiple Win32 profiles may have different title/class expressions.
    var controllerName = GetCurrentControllerName();
    var selected = MaaProcessor.Interface?.Controller?.FirstOrDefault(controller =>
        controller.ControllerType == MaaControllerTypes.Win32
        && !string.IsNullOrWhiteSpace(controllerName)
        && controller.Name?.Equals(controllerName, StringComparison.OrdinalIgnoreCase) == true);
    var profile = selected?.Win32 ?? win32;
    return ApplyRegexFilters(windows, profile.ClassRegex, profile.WindowRegex);
}
